import random, math

# Simulate departments: 9, 6, 7, 7, 11
depts = [0]*9 + [1]*6 + [2]*7 + [3]*7 + [4]*11

# How fast do regular leaks narrow down suspects?
# Suppose each day 3 docs published, each to 2 random depts.
# Mole leaks w.p. 0.65, delay 2 or 3 days.
def sim(plant_day1=False, n_trials=5000):
    # Estimate day caught and canary cost
    scores = []
    for _ in range(n_trials):
        mole = random.randrange(40)
        # Track docs per day
        docs = [] # (day, recips, is_canary, variants)
        leaks = [] # (surface_day, doc_idx, shown_var)
        leaked_set = set()
        canaries_cost = 0.0

        suspects = set(range(40))
        # Decoy known day 2 (1 random non-mole removed)
        decoy = random.choice([i for i in range(40) if i != mole])

        caught_day = 21
        for day in range(1, 22):
            if day == 2:
                suspects.discard(decoy)
            # Check surfaced leaks today
            for sday, didx, svar in leaks:
                if sday == day:
                    _, recips, is_c, vars_map = docs[didx]
                    suspects &= recips
                    if is_c:
                        # 95% accurate, simplify: if <=2 in var, might still need confirmation or logs
                        # In reality Bayes handles 0.95; say if var has mole (95%), narrows mostly to var
                        suspects_var = suspects & {e for e, v in vars_map.items() if v == svar}
                        if len(suspects_var) > 0:
                            suspects = suspects_var # approx
            if len(suspects) == 1:
                caught_day = day
                break

            # Publish regular docs today
            nd = random.choice([2, 3, 4])
            for _ in range(nd):
                d1, d2 = random.sample(range(5), 2)
                recips = {e for e in range(40) if depts[e] in (d1, d2)}
                docs.append((day, recips, False, None))

            # Canary strategy
            if plant_day1 and day == 1:
                # 2 canaries: 19 and 19 covering 38 people orthogonally across depts
                # group by dept
                by_d = [[e for e in range(40) if depts[e] == d] for d in range(5)]
                c1, c2 = {}, {}
                for d_list in by_d:
                    half = len(d_list)//2
                    for idx, e in enumerate(d_list[:half]):
                        c1[e] = idx % 3
                    for idx, e in enumerate(d_list[half:]):
                        c2[e] = idx % 3
                docs.append((day, set(c1.keys()), True, c1))
                docs.append((day, set(c2.keys()), True, c2))
                canaries_cost += 0.02
            elif day >= 3 and len(suspects) <= 18 and len(suspects) > 1:
                # Plant 1 or 2 targeted canaries if no active canary on suspects
                active_c = sum(1 for d0, r, ic, _ in docs if ic and day - d0 <= 2 and len(r & suspects) >= len(suspects)//2)
                if active_c == 0:
                    s_list = sorted(suspects)
                    if len(s_list) <= 3:
                        # Add filler if needed or just 3? Let us use s_list
                        c1 = {e: idx % 3 for idx, e in enumerate(s_list)}
                        docs.append((day, set(c1.keys()), True, c1))
                        canaries_cost += 0.01
                    else:
                        c1 = {e: idx % 3 for idx, e in enumerate(s_list)}
                        c2 = {e: (idx // 3) % 3 for idx, e in enumerate(s_list)}
                        docs.append((day, set(c1.keys()), True, c1))
                        if len(s_list) > 3:
                            docs.append((day, set(c2.keys()), True, c2))
                            canaries_cost += 0.02
                        else:
                            canaries_cost += 0.01

            # End of day leak
            elig = []
            weights = []
            for idx, (d0, recips, is_c, _) in enumerate(docs):
                if day - d0 < 3 and mole in recips and idx not in leaked_set:
                    elig.append(idx)
                    weights.append((1.0 - len(recips)/40.0) if is_c else 1.0)
            if elig and sum(weights) > 0 and random.random() < 0.65:
                chosen = random.choices(elig, weights=weights, k=1)[0]
                leaked_set.add(chosen)
                delay = random.choice([2, 3])
                _, _, is_c, vmap = docs[chosen]
                svar = None
                if is_c:
                    svar = vmap[mole] # approx 95%
                leaks.append((day + delay, chosen, svar))

        v = 1.0 - 0.05 * len(leaks) - canaries_cost
        scores.append((v, caught_day, len(leaks), canaries_cost))
    print(f"plant_day1={str(plant_day1):5s}: avg_V={sum(x[0] for x in scores)/len(scores):.4f}, avg_day={sum(x[1] for x in scores)/len(scores):.2f}, avg_canary_cost={sum(x[3] for x in scores)/len(scores):.4f}")

sim(False)
sim(True)
'

