import random

depts = [0]*9 + [1]*6 + [2]*7 + [3]*7 + [4]*11

def sim(plant_day2=False, n_trials=5000):
    scores = []
    for _ in range(n_trials):
        mole = random.randrange(39) # exclude decoy 39
        docs = []
        leaks = []
        leaked_set = set()
        canaries_cost = 0.02 # Day 1 c1, c2
        suspects = set(range(39))

        # Day 1 docs + 2 canaries
        for d1, d2 in [(1,3), (0,2), (3,4), (0,1)]:
            docs.append((1, {e for e in range(40) if depts[e] in (d1, d2)}, False, None))
        by_d = [[e for e in range(40) if depts[e] == d] for d in range(5)]
        c1, c2 = {}, {}
        for d_list in by_d:
            half = len(d_list)//2
            for idx, e in enumerate(d_list[:half]): c1[e] = idx % 3
            for idx, e in enumerate(d_list[half:]): c2[e] = idx % 3
        docs.append((1, set(c1.keys()), True, c1))
        docs.append((1, set(c2.keys()), True, c2))

        caught_day = 21
        for day in range(1, 22):
            if day >= 2:
                for sday, didx, svar in leaks:
                    if sday == day:
                        _, recips, is_c, vars_map = docs[didx]
                        suspects &= recips
                        if is_c:
                            sv = suspects & {e for e, v in vars_map.items() if v == svar}
                            if sv: suspects = sv
                if len(suspects) == 1:
                    caught_day = day
                    break
                nd = random.choice([2, 3, 4])
                for _ in range(nd):
                    d1, d2 = random.sample(range(5), 2)
                    docs.append((day, {e for e in range(40) if depts[e] in (d1, d2)}, False, None))
                if day == 2 and plant_day2:
                    # 2 orthogonal canaries of size 20
                    all_e = list(range(40))
                    random.shuffle(all_e)
                    ca = {e: idx % 3 for idx, e in enumerate(all_e[:20])}
                    cb = {e: idx % 3 for idx, e in enumerate(all_e[20:])}
                    docs.append((day, set(ca.keys()), True, ca))
                    docs.append((day, set(cb.keys()), True, cb))
                    canaries_cost += 0.02
                elif day >= 3 and 1 < len(suspects) <= 18:
                    active_c = sum(1 for d0, r, ic, _ in docs if ic and day - d0 <= 2 and len(r & suspects) >= max(2, len(suspects)//2) and len(r) <= 20)
                    # Wait: on day 3, day 1 canaries have len(r)=19,21. Only plant new if len(suspects) <= 18 and we want narrower split!
                    narrow_c = sum(1 for d0, r, ic, _ in docs if ic and day - d0 <= 2 and len(r) <= 18)
                    if narrow_c == 0:
                        s_list = sorted(suspects)
                        ca = {e: idx % 3 for idx, e in enumerate(s_list)}
                        docs.append((day, set(ca.keys()), True, ca))
                        canaries_cost += 0.01
                        if len(s_list) > 3:
                            cb = {e: (idx // 3) % 3 for idx, e in enumerate(s_list)}
                            docs.append((day, set(cb.keys()), True, cb))
                            canaries_cost += 0.01
            elig, weights = [], []
            for idx, (d0, recips, is_c, _) in enumerate(docs):
                if day - d0 < 3 and mole in recips and idx not in leaked_set:
                    elig.append(idx)
                    weights.append((1.0 - len(recips)/40.0) if is_c else 1.0)
            if elig and sum(weights) > 0 and random.random() < 0.65:
                chosen = random.choices(elig, weights=weights, k=1)[0]
                leaked_set.add(chosen)
                delay = random.choice([2, 3])
                _, _, is_c, vmap = docs[chosen]
                leaks.append((day + delay, chosen, vmap[mole] if is_c else None))
        v = 1.0 - 0.05 * len(leaks) - canaries_cost
        scores.append((v, caught_day, canaries_cost))
    print(f"plant_day2={str(plant_day2):5s}: avg_V={sum(x[0] for x in scores)/len(scores):.4f}, avg_day={sum(x[1] for x in scores)/len(scores):.2f}, cost={sum(x[2] for x in scores)/len(scores):.4f}")

sim(False)
sim(True)
'

